-- create "channel_credentials" table
CREATE TABLE "channel_credentials" ("id" uuid NOT NULL, "tenant_id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "application_id" uuid NULL, "environment_id" uuid NULL, "channel" character varying NOT NULL, "provider" character varying NOT NULL, "mode" character varying NOT NULL, "name" character varying NOT NULL, "config" jsonb NOT NULL, "secret_ciphertext" bytea NULL, "secret_hint" character varying NOT NULL DEFAULT '', "status" character varying NOT NULL DEFAULT 'pending', "verified_at" timestamptz NULL, "rotated_at" timestamptz NULL, PRIMARY KEY ("id"), CONSTRAINT "channel_credentials_tenant_fk" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON UPDATE NO ACTION ON DELETE RESTRICT, CONSTRAINT "channel_credentials_application_fk" FOREIGN KEY ("tenant_id", "application_id") REFERENCES "applications" ("tenant_id", "id") ON UPDATE NO ACTION ON DELETE RESTRICT, CONSTRAINT "channel_credentials_environment_fk" FOREIGN KEY ("tenant_id", "application_id", "environment_id") REFERENCES "environments" ("tenant_id", "application_id", "id") ON UPDATE NO ACTION ON DELETE RESTRICT, CONSTRAINT "channel_credentials_config_object" CHECK (jsonb_typeof(config) = 'object'::text), CONSTRAINT "channel_credentials_env_needs_app" CHECK ((environment_id IS NULL) OR (application_id IS NOT NULL)), CONSTRAINT "channel_credentials_secret_size" CHECK ((secret_ciphertext IS NULL) OR (octet_length(secret_ciphertext) <= 20000)));
-- create index "channel_credentials_app_scope_key" to table: "channel_credentials"
CREATE UNIQUE INDEX "channel_credentials_app_scope_key" ON "channel_credentials" ("tenant_id", "application_id", "channel") WHERE ((application_id IS NOT NULL) AND (environment_id IS NULL) AND ((status)::text <> 'disabled'::text));
-- create index "channel_credentials_env_scope_key" to table: "channel_credentials"
CREATE UNIQUE INDEX "channel_credentials_env_scope_key" ON "channel_credentials" ("tenant_id", "application_id", "environment_id", "channel") WHERE ((environment_id IS NOT NULL) AND ((status)::text <> 'disabled'::text));
-- create index "channel_credentials_tenant_scope_key" to table: "channel_credentials"
CREATE UNIQUE INDEX "channel_credentials_tenant_scope_key" ON "channel_credentials" ("tenant_id", "channel") WHERE ((application_id IS NULL) AND ((status)::text <> 'disabled'::text));
-- create index "channelcredential_tenant_id_id" to table: "channel_credentials"
CREATE UNIQUE INDEX "channelcredential_tenant_id_id" ON "channel_credentials" ("tenant_id", "id");
